const Popular = () => {
  return (
    <div className="popular">
      <h1>POPULAR IN WOMEN</h1>
      <hr />
      <div className="popular-item">
        {data_product.map()}
      </div>
    </div>
  )
}

export default Popular

{data_product.map((item, i) => {
  return <Item key={i} id={item.id} name={item.name} image={item.image} new_price={item.new_price} old_price={item.old_price}/>
})}

const Shop = () => {
  return (
    <div>
      <Hero />
      <Popular />
    </div>
  )
}

export default Shop

.popular{
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  height: 90vh;
}
.popular h1{
  color: #171717;
  font-size: 50px;
  font-weight: 600;
}
.popular hr{
  width: 200px;
  height: 6px;
  border-radius: 10px;
  background: #252525;
}
.popular-item{
  margin-top: 50px;
  display: flex;
  gap: 30px;
}

.offers{
  width: 65%;
  height: 60vh;
  display: flex;
  margin: auto;
  padding: 0px 140px;
  margin-bottom: 150px;
  background: linear-gradient(180deg, #fde1ff 0%, #e1ffea22 60%);
}
.offers-left{
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.offers-left h1{
  color: #171717;
  font-size: 80px;
  font-weight: 600;
}
.offers-left p{
  color: #171717;
  font-size: 22px;
  font-weight: 600;
}
.offers-left button{
  width: 282px;
  height: 70px;
  border-radius: 35px;
  background: #ff4141;
  border: none;
  color: white;
  font-size: 22px;
  font-weight: 500;
}
